def search_contacts(query, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_contacts"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, account_id=None, error_code=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok(account_id):
        # 60 req/min per account across all endpoints (fallback).
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n < 60

    # Validate
    if not isinstance(query, str) or not query.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string")

    q = query.strip().lower()

    # Resolve exactly one active account that can serve this call (must have contacts).
    accounts = _load("wa_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
    if not active_accounts:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active WhatsApp session available")

    # Choose an active account that actually has contacts rows (so reads don't erroneously return nothing).
    account_id = None
    for a in active_accounts:
        aid = a.get("id")
        if any(isinstance(c, dict) and c.get("account_id") == aid for c in contacts):
            account_id = aid
            break
    if account_id is None:
        # Fall back to any active account; returning an empty result is valid.
        account_id = active_accounts[0].get("id")

    if not _rate_limit_ok(account_id):
        _log("error", account_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests; please retry later")

    # Business rule: only active contacts and case-insensitive contains over display_name, nickname, jid, phone_e164
    out = []
    for c in contacts:
        if not isinstance(c, dict):
            continue
        if c.get("account_id") != account_id:
            continue
        if c.get("status") != "active":
            continue
        hay = []
        for k in ("display_name", "nickname", "jid", "phone_e164"):
            v = c.get(k)
            if isinstance(v, str) and v:
                hay.append(v.lower())
        if any(q in h for h in hay):
            out.append(c)

    # Implementation-defined paging/order: stable sort by display_name (nulls last) then id
    def _key(row):
        name = row.get("display_name")
        name_key = (1, "") if not isinstance(name, str) or not name.strip() else (0, name.strip().lower())
        rid = row.get("id") if isinstance(row.get("id"), str) else ""
        return (name_key[0], name_key[1], rid)

    out.sort(key=_key)

    resp = {
        "object": "list",
        "data": out,
        "count": len(out),
        "account_id": account_id,
    }
    _log("ok", account_id)
    return resp

def list_messages(chat_jid, limit=None, page=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_messages"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, account_id=None, error_code=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok(account_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n < 60

    # Defaults
    if limit is None:
        limit = 20
    if page is None:
        page = 0

    # Validate
    if not isinstance(chat_jid, str) or not chat_jid.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chat_jid is required and must be a non-empty string")
    chat_jid = chat_jid.strip()

    if not isinstance(limit, int):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if not (1 <= limit <= 100):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be within 1..100")
    if not isinstance(page, int):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer")
    if page < 0:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be >= 0")

    accounts = _load("wa_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    chats = _load("chats.json")
    if not isinstance(chats, list):
        chats = []
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    active_ids = [a.get("id") for a in accounts if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
    active_ids = [i for i in active_ids if i]
    if not active_ids:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active WhatsApp account session available")

    # Find an active account that actually has this chat_jid.
    chosen_account_id = None
    chosen_chat = None
    for aid in active_ids:
        for c in chats:
            if isinstance(c, dict) and c.get("account_id") == aid and c.get("jid") == chat_jid:
                chosen_account_id = aid
                chosen_chat = c
                break
        if chosen_chat is not None:
            break

    if chosen_account_id is None:
        # Fall back: some stores may only have messages.chat_jid without chats row; try to infer via messages.
        # If found, accept and list messages without requiring chat row (relaxed to match real-world sync).
        for aid in active_ids:
            for m in messages:
                if isinstance(m, dict) and m.get("account_id") == aid and m.get("chat_jid") == chat_jid:
                    chosen_account_id = aid
                    break
            if chosen_account_id:
                break

    if not chosen_account_id:
        _log("error", active_ids[0], "NOT_FOUND")
        return _err("NOT_FOUND", "Chat not found in the synced store")

    if not _rate_limit_ok(chosen_account_id):
        _log("error", chosen_account_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests; please retry later")

    chat_id = chosen_chat.get("id") if isinstance(chosen_chat, dict) else None

    # Filter messages for this chat
    filtered = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("account_id") != chosen_account_id:
            continue
        if chat_id is not None:
            if m.get("chat_id") != chat_id:
                continue
        else:
            if m.get("chat_jid") != chat_jid:
                continue
        filtered.append(m)

    def _sent_key(m):
        dt = _parse_ts(m.get("sent_at")) or datetime.datetime.min
        mid = m.get("id")
        mid = "" if mid is None else str(mid)
        return (dt, mid)

    # Order sent_at desc, id desc
    filtered.sort(key=_sent_key, reverse=True)

    total = len(filtered)
    offset = page * limit
    page_rows = filtered[offset:offset + limit] if offset < total else []
    has_more = (offset + limit) < total
    next_cursor = None
    if has_more:
        next_cursor = {"page": page + 1, "limit": limit}

    _log("ok", chosen_account_id)
    return {
        "chat_jid": chat_jid,
        "messages": page_rows,
        "page": page,
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def list_chats(limit=None, page=None, sort_by=None, query=None, include_last_message=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_chats"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, account_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(account_id):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= 60:
            return False
        return True

    # Defaults
    if limit is None:
        limit = 20
    if page is None:
        page = 0
    if sort_by is None:
        sort_by = "last_active"
    if include_last_message is None:
        include_last_message = True

    # Validate
    if not isinstance(limit, int):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if not (1 <= limit <= 100):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be within 1..100")
    if not isinstance(page, int):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page must be an integer")
    if page < 0:
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page must be >= 0")
    if sort_by not in ("last_active", "name"):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_by must be one of: last_active, name")
    if query is not None and not isinstance(query, str):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "query must be a string when provided")
    if not isinstance(include_last_message, bool):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_last_message must be a boolean")

    accounts = _load("wa_accounts.json")
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log("error", None, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active WhatsApp session is available")
    acct = active_accounts[0]
    account_id = acct.get("id")

    if not _rate_limit_check(account_id):
        _log("error", account_id, {"code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    chats = _load("chats.json")
    rows = []
    q = query.strip().lower() if isinstance(query, str) and query.strip() else None
    for c in chats:
        if c.get("account_id") != account_id:
            continue
        if c.get("status") not in ("active", "archived"):
            continue
        if q:
            nm = c.get("name")
            jid = c.get("jid")
            hay = []
            if isinstance(nm, str) and nm:
                hay.append(nm.lower())
            if isinstance(jid, str) and jid:
                hay.append(jid.lower())
            if not any(q in h for h in hay):
                continue
        rows.append(c)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    if sort_by == "last_active":
        # last_active_at desc, nulls last, then id
        def key(c):
            dt = _parse_dt(c.get("last_active_at"))
            null_rank = 1 if dt is None else 0
            dtv = dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (null_rank, -dtv.timestamp(), c.get("id") or "")
        rows.sort(key=key)
    else:
        # name asc, nulls last, then id
        def key(c):
            nm = c.get("name")
            null_rank = 1 if not (isinstance(nm, str) and nm.strip()) else 0
            nmv = (nm or "").strip().lower()
            return (null_rank, nmv, c.get("id") or "")
        rows.sort(key=key)

    total = len(rows)
    offset = page * limit
    page_rows = rows[offset: offset + limit]
    has_more = offset + limit < total
    next_cursor = {"page": page + 1} if has_more else None

    # Optionally include last message
    if include_last_message:
        msgs = _load("messages.json")
        msg_by_id = {}
        for m in msgs:
            if m.get("account_id") == account_id:
                mid = m.get("id")
                if isinstance(mid, str):
                    msg_by_id[mid] = m
        enriched = []
        for c in page_rows:
            c2 = dict(c)
            lm_id = c.get("last_message_id")
            lm = None
            if isinstance(lm_id, str) and lm_id in msg_by_id:
                cand = msg_by_id[lm_id]
                if cand.get("chat_id") == c.get("id") and cand.get("account_id") == account_id:
                    lm = cand
            c2["last_message"] = lm
            enriched.append(c2)
        page_rows = enriched

    resp = {
        "chats": page_rows,
        "page": page,
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": sort_by,
        "query": query,
        "include_last_message": include_last_message,
    }
    _log("ok", account_id, {"returned": len(page_rows), "total": total})
    return resp

def get_chat(chat_jid, include_last_message=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_chat"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs_list():
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return logs
        # If file exists but is not a list, treat as empty list to avoid breaking service dynamics
        return []

    def _log(status, account_id=None, error_code=None, detail=None):
        logs = _ensure_logs_list()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok(account_id):
        # Simple per-account rolling window: 60 req/min
        logs = _ensure_logs_list()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n < 60

    def _active_account_with_data():
        accs = _load("wa_accounts.json")
        if not isinstance(accs, list):
            return None
        chats = _load("chats.json")
        if not isinstance(chats, list):
            chats = []
        msgs = _load("messages.json")
        if not isinstance(msgs, list):
            msgs = []
        # choose an active account that has at least some synced data (prefer chats, else messages)
        active = [a for a in accs if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
        if not active:
            return None
        chat_accounts = {c.get("account_id") for c in chats if isinstance(c, dict) and isinstance(c.get("account_id"), str)}
        msg_accounts = {m.get("account_id") for m in msgs if isinstance(m, dict) and isinstance(m.get("account_id"), str)}
        for a in active:
            if a["id"] in chat_accounts:
                return a
        for a in active:
            if a["id"] in msg_accounts:
                return a
        # fallback: any active account (still "available"); reads may return empty
        return active[0]

    if include_last_message is None:
        include_last_message = True

    # Validate inputs
    if not isinstance(chat_jid, str) or not chat_jid.strip():
        _log("error", None, "VALIDATION_ERROR", {"chat_jid": chat_jid})
        return _err("VALIDATION_ERROR", "chat_jid must be a non-empty string", chat_jid=chat_jid)
    if not isinstance(include_last_message, bool):
        _log("error", None, "VALIDATION_ERROR", {"include_last_message": include_last_message})
        return _err("VALIDATION_ERROR", "include_last_message must be a boolean", include_last_message=include_last_message)

    account = _active_account_with_data()
    if not account:
        _log("error", None, "UNAUTHORIZED", {"reason": "no active wa_account"})
        return _err("UNAUTHORIZED", "No active WhatsApp session is available")

    account_id = account["id"]
    if not _rate_limit_ok(account_id):
        _log("error", account_id, "RATE_LIMIT", {"window_seconds": 60, "limit": 60})
        return _err("RATE_LIMIT", "Too many requests; please retry later")

    chats = _load("chats.json")
    if not isinstance(chats, list):
        chats = []

    target = None
    for c in chats:
        if not isinstance(c, dict):
            continue
        if c.get("account_id") == account_id and c.get("jid") == chat_jid:
            target = c
            break

    if not target:
        _log("error", account_id, "NOT_FOUND", {"chat_jid": chat_jid})
        return _err("NOT_FOUND", "Chat not found for the active account", chat_jid=chat_jid)

    resp = {"chat": dict(target)}

    if include_last_message:
        last_mid = target.get("last_message_id")
        last_msg = None
        if isinstance(last_mid, str) and last_mid.strip():
            messages = _load("messages.json")
            if not isinstance(messages, list):
                messages = []
            for m in messages:
                if not isinstance(m, dict):
                    continue
                if m.get("id") == last_mid and m.get("account_id") == account_id and m.get("chat_id") == target.get("id"):
                    last_msg = m
                    break
        resp["last_message"] = dict(last_msg) if last_msg else None

    _log("ok", account_id, None, {"chat_jid": chat_jid, "include_last_message": include_last_message})
    return resp

def get_message_context(message_id, before=None, after=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_message_context"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs_list():
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return logs
        return []

    def _log(status, account_id=None, error_code=None, detail=None):
        logs = _ensure_logs_list()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok(account_id):
        logs = _ensure_logs_list()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n < 60

    def _active_account_with_data():
        accs = _load("wa_accounts.json")
        if not isinstance(accs, list):
            return None
        msgs = _load("messages.json")
        if not isinstance(msgs, list):
            msgs = []
        active = [a for a in accs if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
        if not active:
            return None
        msg_accounts = {m.get("account_id") for m in msgs if isinstance(m, dict) and isinstance(m.get("account_id"), str)}
        for a in active:
            if a["id"] in msg_accounts:
                return a
        return active[0]

    if before is None:
        before = 5
    if after is None:
        after = 5

    if message_id is None or not isinstance(message_id, str) or not message_id.strip():
        _log("error", None, "VALIDATION_ERROR", {"message_id": message_id})
        return _err("VALIDATION_ERROR", "message_id must be a non-empty string", message_id=message_id)
    if not isinstance(before, int) or before < 0:
        _log("error", None, "VALIDATION_ERROR", {"before": before})
        return _err("VALIDATION_ERROR", "before must be an integer >= 0", before=before)
    if not isinstance(after, int) or after < 0:
        _log("error", None, "VALIDATION_ERROR", {"after": after})
        return _err("VALIDATION_ERROR", "after must be an integer >= 0", after=after)

    account = _active_account_with_data()
    if not account:
        _log("error", None, "UNAUTHORIZED", {"reason": "no active wa_account"})
        return _err("UNAUTHORIZED", "No active WhatsApp session is available")

    account_id = account["id"]
    if not _rate_limit_ok(account_id):
        _log("error", account_id, "RATE_LIMIT", {"window_seconds": 60, "limit": 60})
        return _err("RATE_LIMIT", "Too many requests; please retry later")

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    target = None
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("account_id") == account_id and m.get("id") == message_id:
            target = m
            break

    if not target:
        _log("error", account_id, "NOT_FOUND", {"message_id": message_id})
        return _err("NOT_FOUND", "Message not found for the active account", message_id=message_id)

    def _key(mrow):
        s_at = _parse_ts(mrow.get("sent_at")) or datetime.datetime.min
        mid = mrow.get("id") or ""
        return (s_at, mid)

    tgt_key = _key(target)
    chat_id = target.get("chat_id")

    same_chat = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("account_id") != account_id:
            continue
        if m.get("chat_id") != chat_id:
            continue
        same_chat.append(m)

    prev = [m for m in same_chat if _key(m) < tgt_key]
    prev.sort(key=lambda r: (_key(r)[0], _key(r)[1]), reverse=True)
    prev = prev[:before]

    nxt = [m for m in same_chat if _key(m) > tgt_key]
    nxt.sort(key=lambda r: (_key(r)[0], _key(r)[1]))
    nxt = nxt[:after]

    _log("ok", account_id, None, {"message_id": message_id, "before": before, "after": after})
    return {
        "message": dict(target),
        "before": [dict(m) for m in prev],
        "after": [dict(m) for m in nxt],
    }

def send_message(recipient, message, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "send_message"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _rate_limited(account_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n >= 60  # 60 sends/min per active account

    def _infer_chat_type(jid):
        if not isinstance(jid, str):
            return "unknown"
        if jid.endswith("@g.us"):
            return "group"
        if jid.endswith("@broadcast"):
            return "broadcast"
        if jid.endswith("@s.whatsapp.net") or jid.endswith("@c.us"):
            return "direct"
        return "unknown"

    def _new_id(prefix, existing):
        # monotonic-ish id with collision check
        for _ in range(10):
            cand = f"{prefix}_{int(time.time()*1000)}_{random.randint(1000,9999)}"
            if all((r.get("id") != cand) for r in existing):
                return cand
        return f"{prefix}_{int(time.time()*1000)}_{len(existing)+1}"

    # Validate inputs
    if not isinstance(recipient, str) or not recipient.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "recipient is required and must be a non-empty string")
    if not isinstance(message, str) or len(message) < 1:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "message is required and must be a non-empty string")

    accounts = _load("wa_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active WhatsApp session available")
    account = active_accounts[0]
    account_id = account.get("id")
    wa_jid = account.get("wa_jid")

    # Session state check for sending
    if account.get("status") != "active":
        _log("error", account_id, "CONFLICT")
        return _err("CONFLICT", "Session is not in a state that permits sending")

    if _rate_limited(account_id):
        _log("error", account_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    chats = _load("chats.json")
    if not isinstance(chats, list):
        chats = []
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    # Upsert chat for (account_id, jid=recipient)
    chat = None
    for c in chats:
        if c.get("account_id") == account_id and c.get("jid") == recipient:
            chat = c
            break

    if chat is not None and chat.get("status") == "deleted":
        _log("error", account_id, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot send to a deleted chat")

    if chat is None:
        chat_id = _new_id("chat", chats)
        chat = {
            "id": chat_id,
            "account_id": account_id,
            "jid": recipient,
            "chat_type": _infer_chat_type(recipient),
            "name": None,
            "last_message_id": None,
            "last_active_at": None,
            "unread_count": 0,
            "is_muted": False,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        # Uniqueness (account_id, jid)
        for c in chats:
            if c.get("account_id") == account_id and c.get("jid") == recipient:
                chat = c
                break
        else:
            chats.append(chat)
    else:
        # ensure chat is sendable
        if chat.get("status") not in ("active", "archived"):
            _log("error", account_id, "CONFLICT")
            return _err("CONFLICT", "Chat is not in a state that permits sending")

    if not chat.get("id"):
        _log("error", account_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Recipient chat could not be resolved or created")

    # Insert message row
    msg_id = _new_id("msg", messages)
    new_msg = {
        "id": msg_id,
        "account_id": account_id,
        "chat_id": chat.get("id"),
        "chat_jid": chat.get("jid"),
        "wa_message_id": None,
        "sender_jid": wa_jid if isinstance(wa_jid, str) and wa_jid else "unknown",
        "direction": "out",
        "message_type": "text",
        "text": message,
        "sent_at": now,
        "status": "queued",
        "failure_reason": None,
        "reply_to_message_id": None,
        "metadata": {},
        "created_at": now,
        "updated_at": now
    }

    messages.append(new_msg)

    # Update chat denormalized pointers
    chat["last_message_id"] = msg_id
    chat["last_active_at"] = now
    chat["updated_at"] = now
    if chat.get("status") == "archived":
        # Keep archived status; do not auto-unarchive unless explicit tool exists
        pass

    _save("messages.json", messages)
    _save("chats.json", chats)

    _log("ok", account_id, None)
    return {"message": new_msg, "chat": {"id": chat.get("id"), "jid": chat.get("jid"), "status": chat.get("status")}}

def search_messages(query, chat_jid=None, limit=None, page=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_messages"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _rate_limited(account_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n >= 120  # 120 req/min per active account

    # Validate
    if not isinstance(query, str) or not query.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string")
    if limit is None:
        limit = 10
    if page is None:
        page = 0
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer within 1..50")
    if not isinstance(page, int) or page < 0:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 0")
    if chat_jid is not None and (not isinstance(chat_jid, str) or not chat_jid.strip()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chat_jid must be a non-empty string when provided")

    accounts = _load("wa_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active WhatsApp session available")
    account = active_accounts[0]
    account_id = account.get("id")

    if _rate_limited(account_id):
        _log("error", account_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    chats = _load("chats.json")
    if not isinstance(chats, list):
        chats = []
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    chat_id = None
    if chat_jid is not None:
        for c in chats:
            if c.get("account_id") == account_id and c.get("jid") == chat_jid:
                chat_id = c.get("id")
                break
        if chat_id is None:
            _log("error", account_id, "NOT_FOUND")
            return _err("NOT_FOUND", "Chat not found for chat_jid")

    q = query.casefold()

    def _sent_key(m):
        dt = _parse_dt(m.get("sent_at")) or datetime.datetime.min
        mid = m.get("id") or ""
        return (dt, mid)

    filtered = []
    for m in messages:
        if m.get("account_id") != account_id:
            continue
        if chat_id is not None and m.get("chat_id") != chat_id:
            continue
        if m.get("message_type") != "text":
            continue
        txt = m.get("text")
        if not isinstance(txt, str):
            continue
        if q in txt.casefold():
            filtered.append(m)

    filtered.sort(key=lambda m: (_sent_key(m)[0], _sent_key(m)[1]), reverse=True)

    total = len(filtered)
    offset = page * limit
    page_rows = filtered[offset:offset + limit]
    has_more = (offset + limit) < total

    _log("ok", account_id, None)
    return {
        "data": page_rows,
        "meta": {
            "query": query,
            "chat_jid": chat_jid,
            "limit": limit,
            "page": page,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None
        }
    }

def list_contacts(limit=None, page=None, sort_by=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_contacts"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_s, account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _rate_limited(account_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if r.get("account_id") != account_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n >= 120  # 120 req/min per active account

    # Defaults
    if limit is None:
        limit = 50
    if page is None:
        page = 0
    if sort_by is None:
        sort_by = "display_name"
    if status is None:
        status = "active"

    # Validate
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer within 1..100")
    if not isinstance(page, int) or page < 0:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 0")
    if sort_by not in ("display_name", "last_seen"):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by must be one of: display_name, last_seen")
    if status not in ("active", "blocked", "deleted"):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, blocked, deleted")

    accounts = _load("wa_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_accounts = [a for a in accounts if a.get("status") == "active"]
    if not active_accounts:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active WhatsApp session available")
    account = active_accounts[0]
    account_id = account.get("id")

    if _rate_limited(account_id):
        _log("error", account_id, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    scoped = [c for c in contacts if c.get("account_id") == account_id and c.get("status") == status]

    def _norm_name(v):
        if v is None:
            return (1, "")
        if not isinstance(v, str):
            return (1, "")
        s = v.strip()
        if not s:
            return (1, "")
        return (0, s.casefold())

    def _dt_key(v):
        dt = _parse_dt(v)
        if dt is None:
            return (1, datetime.datetime.min)
        return (0, dt)

    if sort_by == "display_name":
        scoped.sort(key=lambda c: (_norm_name(c.get("display_name"))[0], _norm_name(c.get("display_name"))[1], c.get("id") or ""))
    else:  # last_seen
        # last_seen desc nulls last
        scoped.sort(key=lambda c: (_dt_key(c.get("last_seen_at"))[0], _dt_key(c.get("last_seen_at"))[1], c.get("id") or ""), reverse=True)

    total = len(scoped)
    offset = page * limit
    page_rows = scoped[offset:offset + limit]
    has_more = (offset + limit) < total

    _log("ok", account_id, None)
    return {
        "data": page_rows,
        "meta": {
            "limit": limit,
            "page": page,
            "sort_by": sort_by,
            "status": status,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None
        }
    }

def get_contact(contact_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
