def update_contact(contact_id, display_name=None, nickname=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_out, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "service": "whatsapp_mcp",
            "endpoint": "update_contact",
            "credential_id": credential_id,
            "status": status_out,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if contact_id is None or not isinstance(contact_id, str) or not contact_id.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_id is required and must be a non-empty string")

    if display_name is not None:
        if not isinstance(display_name, str) or len(display_name.strip()) < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "display_name must be a non-empty string when provided")
        display_name = display_name.strip()

    if nickname is not None:
        if not isinstance(nickname, str) or len(nickname.strip()) < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "nickname must be a non-empty string when provided")
        nickname = nickname.strip()

    allowed_status = {"active", "blocked", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, blocked, deleted")

    if display_name is None and nickname is None and status is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No fields to update")

    # Ambient auth
    accounts = _load("wa_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    active_acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str):
            active_acct = a
            break
    if not active_acct:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active WhatsApp account session available")

    # Rate limit (writes: 30/min)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != "update_contact":
            continue
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt.replace(tzinfo=None) >= cutoff:
            recent += 1
    if recent >= 30:
        _log("error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    contacts = _load("contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    idx = None
    row = None
    for i, c in enumerate(contacts):
        if isinstance(c, dict) and c.get("id") == contact_id and c.get("account_id") == active_acct["id"]:
            idx = i
            row = c
            break
    if row is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found for active account")

    old_status = row.get("status")
    if not isinstance(old_status, str):
        old_status = "active"

    # Lifecycle enforcement
    transitions = {
        "active": {"blocked", "deleted"},
        "blocked": {"active", "deleted"},
        "deleted": set()
    }

    changed = False

    if status is not None and status != old_status:
        if old_status not in transitions:
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Contact is in an unknown state and cannot be transitioned", current_status=old_status)
        if status not in transitions[old_status]:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition contact from '{old_status}' to '{status}'",
                        from_status=old_status, to_status=status)
        row["status"] = status
        changed = True

    if display_name is not None and display_name != row.get("display_name"):
        row["display_name"] = display_name
        changed = True

    if nickname is not None and nickname != row.get("nickname"):
        row["nickname"] = nickname
        changed = True

    if not changed:
        # Idempotent no-op should still be observable; but "no success without effect" applies to mutations.
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Update would not change anything")

    row["updated_at"] = now
    contacts[idx] = row
    _save("contacts.json", contacts)

    _log("ok")
    return {"contact": row}

def update_chat(chat_jid, status=None, is_muted=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0307000" if __import__("os").path.isdir("./environment_mix/0307000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_chat"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_logs_list():
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return logs
        return []

    def _log(status_out, account_id=None, error_code=None, detail=None):
        logs = _ensure_logs_list()
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_out,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok(account_id):
        logs = _ensure_logs_list()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n < 60

    def _active_account_with_data():
        accs = _load("wa_accounts.json")
        if not isinstance(accs, list):
            return None
        chats = _load("chats.json")
        if not isinstance(chats, list):
            chats = []
        active = [a for a in accs if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str)]
        if not active:
            return None
        chat_accounts = {c.get("account_id") for c in chats if isinstance(c, dict) and isinstance(c.get("account_id"), str)}
        for a in active:
            if a["id"] in chat_accounts:
                return a
        return active[0]

    def _allowed_transition(frm, to):
        transitions = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set(),
        }
        return to in transitions.get(frm, set())

    # Validate
    if not isinstance(chat_jid, str) or not chat_jid.strip():
        _log("error", None, "VALIDATION_ERROR", {"chat_jid": chat_jid})
        return _err("VALIDATION_ERROR", "chat_jid must be a non-empty string", chat_jid=chat_jid)

    if status is not None:
        if not isinstance(status, str):
            _log("error", None, "VALIDATION_ERROR", {"status": status})
            return _err("VALIDATION_ERROR", "status must be a string", status=status)
        if status not in ("active", "archived", "deleted"):
            _log("error", None, "VALIDATION_ERROR", {"status": status})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", status=status)

    if is_muted is not None and not isinstance(is_muted, bool):
        _log("error", None, "VALIDATION_ERROR", {"is_muted": is_muted})
        return _err("VALIDATION_ERROR", "is_muted must be a boolean", is_muted=is_muted)

    if status is None and is_muted is None:
        _log("error", None, "VALIDATION_ERROR", {"reason": "no fields"})
        return _err("VALIDATION_ERROR", "At least one of status or is_muted must be provided")

    account = _active_account_with_data()
    if not account:
        _log("error", None, "UNAUTHORIZED", {"reason": "no active wa_account"})
        return _err("UNAUTHORIZED", "No active WhatsApp session is available")

    account_id = account["id"]
    if not _rate_limit_ok(account_id):
        _log("error", account_id, "RATE_LIMIT", {"window_seconds": 60, "limit": 60})
        return _err("RATE_LIMIT", "Too many requests; please retry later")

    chats = _load("chats.json")
    if not isinstance(chats, list):
        chats = []

    idx = None
    for i, c in enumerate(chats):
        if not isinstance(c, dict):
            continue
        if c.get("account_id") == account_id and c.get("jid") == chat_jid:
            idx = i
            break

    if idx is None:
        _log("error", account_id, "NOT_FOUND", {"chat_jid": chat_jid})
        return _err("NOT_FOUND", "Chat not found for the active account", chat_jid=chat_jid)

    chat = chats[idx]
    changed = False

    # Lifecycle update
    if status is not None:
        cur = chat.get("status")
        if cur not in ("active", "archived", "deleted"):
            _log("error", account_id, "CONFLICT", {"current_status": cur})
            return _err("CONFLICT", "Chat has an unknown/invalid current status; cannot apply transition", current_status=cur)
        if status != cur:
            if not _allowed_transition(cur, status):
                _log("error", account_id, "INVALID_TRANSITION", {"from": cur, "to": status})
                return _err("INVALID_TRANSITION", f"Illegal status transition for chat: {cur} -> {status}", from_status=cur, to_status=status)
            chat["status"] = status
            changed = True

    # Mutable flag update
    if is_muted is not None:
        if chat.get("is_muted") != is_muted:
            chat["is_muted"] = is_muted
            changed = True

    if not changed:
        # Idempotent: request had no effect; still return current row (real services often do this)
        _log("ok", account_id, None, {"chat_jid": chat_jid, "idempotent": True})
        return {"chat": dict(chat), "updated": False}

    chat["updated_at"] = _now()
    chats[idx] = chat
    _save("chats.json", chats)

    _log("ok", account_id, None, {"chat_jid": chat_jid, "updated_fields": {"status": status, "is_muted": is_muted}})
    return {"chat": dict(chat), "updated": True}

